def copy_filenames(apps, schema_editor):
    """Files stored so far are downloaded under the last part of their key."""
    for model_name, field in (("VisitDocument", "document"), ("VisitExport", "file")):
        model = apps.get_model("sure", model_name)
        for obj in model.objects.exclude(**{field: ""}).exclude(
            **{f"{field}__isnull": True}
        ):
            obj.filename = getattr(obj, field).name.rsplit("/", 1)[-1]
            obj.save(update_fields=["filename"])


